// === Tab: mySketch ===
const SZE = 50;
let HUE, HUE_DEV = 90; // hue and deviation wil set in setup()

let pts, segments;
let S_H, CLR, NUMX, NUMY;

function setup() {
	createCanvas(SZE*~~(windowWidth/SZE), SZE*~~(windowHeight/SZE));
	describe("grid of points connected together forming short connected lines")
	frameRate(60);
	background("rgb(0,0,11)");
	colorMode(HSB);

	S_H = ~~(SZE / 2);
	strokeWeight(S_H * 0.85);
	strokeCap(ROUND);
	strokeJoin(ROUND);
	noFill();

	// color
	HUE = ~~random(360);
	HUE_DEV = ~~random(60, 120);

	// init
	pts = [];
	NUMX = ~~(width/SZE);
	NUMY = ~~(height/SZE);
	for (let j = 0; j < NUMY; j++) {
		for (let i = 0; i < NUMX; i++) {
			pts.push({i, j, seg: random() > 0.1 ? 0 : -1}); // value = segment id, -1 = forced hole in space
		}
	}

	segments = [];
	segments.push({clr: "rgb(4,4,48)", pts: []})
}

function draw() {
	// new seg
	newSegment();
	extendSegment();

	if (false) {
		for (let p of pts) {
			if (p.seg < 0) {	
				const seg = segments[0]; // borrow color from seg[0]
				stroke(seg.clr);
			} else {			
				var seg = segments[p.seg];
				stroke(seg.clr);
			}
			point(p.i * SZE + S_H, p.j * SZE + S_H);
		}
	}

	for (let i = segments.length - 1; i >= 0; i--) {
		var seg = segments[i];
		stroke(seg.clr);
		beginShape();
		for (let p of seg.pts) {
			vertex(p.i * SZE + S_H, p.j * SZE + S_H);
		}
		endShape();
	}
}

function newSegment() {
	if (segments.length > min(NUMX, NUMY) * 2) return;

	const x = ~~random(NUMX)
	const y = ~~random(NUMY)
	const i = y*NUMX + x; 
	const p = pts[i];
	if (p.seg === 0) {
		p.seg = segments.length;
		// const clr = lerpColor(color("darkred"), color("navy"), random()); // strokeJoin(ROUND);
		const clr = color(HUE+random(-HUE_DEV, HUE_DEV), random(50, 90), random(60, 90), 0.95);
		segments.push({clr, pts: [p]});
		randomWalk(p)
	}
}

function extendSegment() {
	var seg = segments[~~random(1, segments.length)];
	if (seg) randomWalk(seg.pts[seg.pts.length-1]);
}

function randomWalk(p) {
	const entropy = [];
	const D = 1;
	for (let j = -D; j <= D; j++) { // y
		for (let i = -D; i <= D; i++) { // x
			px = p.i + i;
			py = p.j + j;
			// if (!(i === 0 && j === 0) && px >= 0 && px < NUMX && py >= 0 && py < NUMY) {
			if (i != 0 && j != 0 && px >= 0 && px < NUMX && py >= 0 && py < NUMY) {
				if (pts[py*NUMX+px].seg === 0) {
					entropy.push({j: py, i: px});
				}
			}
		}		
	}

	if (entropy.length > 0) {
		const choice = random(entropy);
		const connPt = pts[choice.j*NUMX+choice.i];
		connPt.seg = p.seg;
		segments[connPt.seg].pts.push(connPt);
	}
}

function mousePressed() {
	setup();
}
